import threading
from typing import Optional

class BankAccount:
    def __init__(self, balance: float, account_id: str = "acc_1"):
        if balance < 0:
            raise ValueError("Initial balance cannot be negative")
        self.account_id = account_id
        self.balance = balance
        self._lock = threading.RLock()

    def withdraw(self, amount: float) -> bool:
        """Thread-safe atomic withdrawal."""
        if amount <= 0:
            raise ValueError("Withdrawal amount must be positive")

        with self._lock:
            if self.balance >= amount:
                self.balance -= amount
                return True
            return False

    def deposit(self, amount: float) -> None:
        """Thread-safe atomic deposit."""
        if amount <= 0:
            raise ValueError("Deposit amount must be positive")
        with self._lock:
            self.balance += amount

    def transfer(self, target_account: 'BankAccount', amount: float) -> bool:
        """Thread-safe transfer with deadlock prevention via lock ordering."""
        if amount <= 0:
            raise ValueError("Transfer amount must be positive")

        # Order locks by account_id to prevent AB-BA deadlock
        first_lock, second_lock = (
            (self._lock, target_account._lock)
            if self.account_id < target_account.account_id
            else (target_account._lock, self._lock)
        )

        with first_lock:
            with second_lock:
                if self.balance >= amount:
                    self.balance -= amount
                    target_account.balance += amount
                    return True
                return False

import socket
from collections import OrderedDict
from typing import Any, Optional

class LRUCache:
    def __init__(self, capacity: int = 500):
        self.capacity = capacity
        self._cache = OrderedDict()

    def put(self, key: str, value: Any) -> None:
        if key in self._cache:
            self._cache.move_to_end(key)
        self._cache[key] = value
        if len(self._cache) > self.capacity:
            self._cache.popitem(last=False)

    def get(self, key: str) -> Optional[Any]:
        if key not in self._cache:
            return None
        self._cache.move_to_end(key)
        return self._cache[key]

class DataProcessor:
    def __init__(self, host: str = "127.0.0.1", port: int = 8080, max_cache: int = 500):
        self.host = host
        self.port = port
        self.cache = LRUCache(capacity=max_cache)
        self.history_limit = 1000
        self.history = []

    def fetch_and_cache(self, key: str, data: str) -> None:
        """Stores data in bounded LRU cache to prevent memory leaks."""
        self.cache.put(key, data * 1000)
        if len(self.history) >= self.history_limit:
            self.history.pop(0)
        self.history.append(data)

    def send_log(self, message: str, timeout: float = 2.0) -> bool:
        """Sends log message ensuring socket is cleanly closed even on network errors."""
        try:
            with socket.create_connection((self.host, self.port), timeout=timeout) as s:
                s.sendall(message.encode('utf-8'))
                return True
        except (socket.error, socket.timeout) as e:
            return False

import jwt
import os
import time
from typing import Optional, Dict, Any

JWT_SECRET = os.getenv("JWT_SECRET")
if not JWT_SECRET:
    JWT_SECRET = os.urandom(32).hex()

ALGORITHM = "HS256"

def create_user_token(user_id: str, role: str = "user", expires_in: int = 3600) -> str:
    """Creates a cryptographically signed JWT token."""
    payload = {
        "sub": str(user_id),
        "role": role,
        "iat": int(time.time()),
        "exp": int(time.time() + expires_in)
    }
    return jwt.encode(payload, JWT_SECRET, algorithm=ALGORITHM)

def verify_user_token(token: str) -> Optional[Dict[str, Any]]:
    """Verifies JWT token ensuring signature and expiration validity."""
    try:
        payload = jwt.decode(
            token,
            JWT_SECRET,
            algorithms=[ALGORITHM],
            options={
                "verify_signature": True,
                "require": ["exp", "iat", "sub"]
            }
        )
        return payload
    except (jwt.ExpiredSignatureError, jwt.InvalidTokenError):
        return None

