const { validateEmail, mergeUserData } = require('./redos_regex');

describe('Security and Performance Tests', () => {
    test('validateEmail handles ReDoS attack strings in <5ms', () => {
        const attackString = 'a'.repeat(50) + '!';
        const start = Date.now();
        const result = validateEmail(attackString);
        const duration = Date.now() - start;

        expect(result).toBe(false);
        expect(duration).toBeLessThan(10);
    });

    test('mergeUserData blocks prototype pollution', () => {
        const payload = JSON.parse('{"__proto__": {"polluted": true}}');
        const target = {};
        mergeUserData(target, payload);

        expect({}.polluted).toBeUndefined();
    });
});
